<script setup lang="ts">
import {branding,formatDate} from '../ui/branding'
import {computed,ref,watch,nextTick,onBeforeUnmount} from 'vue'
import * as echarts from 'echarts'
import {dark,chartTheme} from '../ui/preferences'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {api,message} from '../api/client'
const route=useRoute(),router=useRouter(),admin=computed(()=>route.path.startsWith('/admin/'))
const result=ref<any>(null),error=ref(''),loading=ref(false),range=ref<[Date,Date]|null>(null)
const filters=ref<Record<string,string>>({}),grain=ref('day'),dimension=ref('request_model'),modelScope=ref('either'),advanced=ref(false)
const options=ref<Record<string,any[]>>({}),optionError=ref(''),optionsLoading=ref(false),applied=ref<Record<string,string>>({})
const filterKeys=computed(()=>admin.value?['model','api_key_id','provider_id','user_id','user_group_id','operation','protocol']:['model','api_key_id','operation'])
const dimensionKeys=computed(()=>admin.value?['request_model','logical_model','provider_id','user_id','user_group_id','api_key_id','operation','protocol']:['request_model','logical_model','api_key_id','operation'])
const labels:Record<string,string>={user_id:'用户',user_group_id:'用户组',api_key_id:'API Key',provider_id:'模型供应商账号',model:'模型',request_model:'请求模型',logical_model:'实际模型',protocol:'协议',operation:'接口',requests:'请求数',success:'成功请求',failure:'失败 / 取消',failure_rate:'失败率',success_rate:'成功率',active_users:'活跃用户',input_tokens:'输入 Token',output_tokens:'输出 Token',cached_tokens:'缓存 Token',total_tokens:'总 Token',usage_unavailable:'Token 不完整请求',token_coverage:'Token 完整率',average_ttft_ms:'平均首字延迟',average_tokens_per_second:'平均生成速率',request_share:'请求占比',token_share:'Token 占比'}
const operationOptions=[{value:'chat',label:'Chat Completions'},{value:'responses',label:'Responses'},{value:'messages',label:'Anthropic Messages'},{value:'embeddings',label:'Embeddings（向量）'},{value:'rerank',label:'Rerank（重排）'},{value:'images',label:'Images（图像）'}]
const visibleFilters=computed(()=>advanced.value?filterKeys.value:filterKeys.value.filter(k=>['model','api_key_id','operation'].includes(k)))
function choices(key:string){return key==='operation'?operationOptions:options.value[key]||[]}
function labelFor(key:string,value:string){return choices(key).find(o=>o.value===value)?.label||value}
function formatMetric(key:string,value:any){if(value==null||!Number.isFinite(Number(value)))return '—';const decimals=key==='average_ttft_ms'?1:['failure_rate','success_rate','token_coverage','request_share','token_share','average_tokens_per_second'].includes(key)?2:0;return Number(value).toLocaleString('zh-CN',{minimumFractionDigits:decimals,maximumFractionDigits:decimals})}
function unit(key:string){return ['failure_rate','success_rate','token_coverage','request_share','token_share'].includes(key)?'%':key==='average_ttft_ms'?'ms':key==='average_tokens_per_second'?'Token/s':''}
const cards=['total_tokens','requests','success_rate','token_coverage','input_tokens','output_tokens','cached_tokens','active_users']
const tableMetrics=['requests','success','failure','success_rate','total_tokens','input_tokens','output_tokens','cached_tokens','average_ttft_ms','average_tokens_per_second']
const chips=computed(()=>filterKeys.value.filter(k=>applied.value[k]).map(k=>({key:k,label:labels[k]+': '+labelFor(k,applied.value[k]!)})))
const hasData=computed(()=>result.value?.summary.requests>0)
const logAvailable=computed(()=>admin.value&&result.value&&new Date(result.value.end).getTime()-new Date(result.value.start).getTime()<=31*86400000)
const dimensionPage=ref(1),timePage=ref(1),sortKey=ref('total_tokens'),sortOrder=ref('descending')
const breakdownRows=computed(()=>[...(result.value?.breakdown||[])].sort((a,b)=>{const x=a[sortKey.value],y=b[sortKey.value];if(x==null)return y==null?0:1;if(y==null)return -1;return (Number(x)-Number(y))*(sortOrder.value==='ascending'?1:-1)}))
const visibleBreakdown=computed(()=>breakdownRows.value.slice((dimensionPage.value-1)*10,dimensionPage.value*10))
const visibleTimeline=computed(()=>result.value?.series.slice((timePage.value-1)*12,timePage.value*12)||[])
function sortRows(event:any){sortKey.value=event.prop||'total_tokens';sortOrder.value=event.order||'descending';dimensionPage.value=1}
let generation=0,controller:AbortController|undefined,optionController:AbortController|undefined
function queryValue(key:string){return typeof route.query[key]==='string'?String(route.query[key]):''}
async function load(){
 const mine=++generation;controller?.abort();const request=new AbortController();controller=request;loading.value=true;error.value=''
 filters.value=Object.fromEntries(filterKeys.value.map(k=>[k,queryValue(k)]));grain.value=queryValue('grain')==='hour'?'hour':'day';dimension.value=dimensionKeys.value.includes(queryValue('dimension'))?queryValue('dimension'):'request_model';modelScope.value=queryValue('model_scope')||'either'
 const start=new Date(queryValue('start')),end=new Date(queryValue('end'));range.value=!isNaN(start.getTime())&&!isNaN(end.getTime())?[start,end]:null
 if(filterKeys.value.some(k=>!['model','api_key_id','operation'].includes(k)&&filters.value[k]))advanced.value=true
 const query:Record<string,string>={grain:grain.value,dimension:dimension.value,model_scope:modelScope.value};for(const k of filterKeys.value)if(filters.value[k])query[k]=filters.value[k]!;if(queryValue('start'))query.start=queryValue('start');if(queryValue('end'))query.end=queryValue('end')
 try{const data=(await api.get((admin.value?'/admin':'/portal')+'/usage',{params:query,signal:request.signal,timeout:20000})).data.data;if(mine===generation){result.value=data;applied.value=query;dimensionPage.value=timePage.value=1;range.value=[new Date(data.start),new Date(data.end)]}}
 catch(e){if(mine===generation&&!request.signal.aborted)error.value=message(e)}finally{if(mine===generation)loading.value=false}
}
async function loadOptions(){optionController?.abort();const request=new AbortController();optionController=request;optionsLoading.value=true;optionError.value='';try{const d=(await api.get((admin.value?'/admin':'/portal')+'/usage/options',{signal:request.signal,timeout:15000})).data.data;if(optionController===request)options.value=d}catch(e){if(!request.signal.aborted)optionError.value='筛选选项暂时无法加载，可直接输入模型名称或 ID'}finally{if(optionController===request)optionsLoading.value=false}}
async function search(){
 const query:Record<string,string>={grain:grain.value,dimension:dimension.value,model_scope:modelScope.value}
 for(const k of filterKeys.value){const value=(filters.value[k]||'').trim();if(value){if(k.endsWith('_id')&&!/^[1-9]\d*$/.test(value)){ElMessage.warning(labels[k]+'请输入有效 ID 或从选项选择');return}query[k]=value}}
 if(range.value){const [start,end]=range.value;if(!Number.isFinite(start.getTime())||!Number.isFinite(end.getTime())||start>=end||end.getTime()-start.getTime()>366*86400000){ElMessage.warning('时间范围须大于 0 且不超过 366 天');return}query.start=start.toISOString();query.end=end.toISOString()}
 const next=router.resolve({path:route.path,query}).fullPath;if(next===route.fullPath)await load();else await router.replace({path:route.path,query})
}
async function preset(value:string){const end=new Date();let start:Date;if(value==='today'){const shifted=new Date(end.getTime()+8*3600000);start=new Date(Date.UTC(shifted.getUTCFullYear(),shifted.getUTCMonth(),shifted.getUTCDate())-8*3600000)}else start=new Date(end.getTime()-Number(value)*3600000);range.value=[start,end];grain.value=value==='today'||value==='24'?'hour':'day';await search()}
async function reset(){filters.value={};range.value=null;grain.value='day';dimension.value='request_model';modelScope.value='either';advanced.value=false;await search()}
async function removeChip(key:string){const query={...applied.value};delete query[key];await router.replace({path:route.path,query})}
function logQuery(){const query:Record<string,string>={start:result.value.start,end:result.value.end};for(const k of filterKeys.value)if(applied.value[k])query[k]=applied.value[k]!;if(query.model&&applied.value.model_scope!=='either'){query[applied.value.model_scope==='request'?'request_model':'logical_model']=query.model;delete query.model}return query}
function drill(row:any){if(!logAvailable.value||!row.value||row.value==='0')return;const query=logQuery(),key=result.value.dimension;query[key]=row.value;void router.push({path:'/admin/call-logs',query})}
function timelineLogs(row:any){if(!logAvailable.value||!row.requests)return;const begin=new Date(row.bucket).getTime(),duration=result.value.grain==='hour'?3600000:86400000;const query=logQuery();query.start=new Date(Math.max(begin,new Date(result.value.start).getTime())).toISOString();query.end=new Date(Math.min(begin+duration,new Date(result.value.end).getTime())).toISOString();void router.push({path:'/admin/call-logs',query})}
const chartHost=ref<HTMLElement>(),chartMetric=ref('tokens');let chart:echarts.ECharts|undefined
const chartMetrics=[{value:'tokens',label:'Token 用量'},{value:'requests',label:'请求与结果'},{value:'success_rate',label:'成功率'},{value:'average_ttft_ms',label:'首字延迟'},{value:'average_tokens_per_second',label:'生成速率'}]
async function renderChart(){await nextTick();if(!chartHost.value||!result.value)return;chart?.dispose();chart=echarts.init(chartHost.value);const rows=result.value.series,keys=chartMetric.value==='tokens'?['total_tokens','input_tokens','output_tokens','cached_tokens']:chartMetric.value==='requests'?['requests','success','failure']:[chartMetric.value];chart.setOption({grid:{left:65,right:28,top:55,bottom:55},legend:{top:8},tooltip:{trigger:'axis',valueFormatter:(value:any)=>value==null?'未上报':formatMetric(keys[0]!,value)+unit(keys[0]!)},xAxis:{type:'category',boundaryGap:false,data:rows.map((r:any)=>formatDate(r.bucket))},yAxis:{type:'value',min:0,max:chartMetric.value==='success_rate'?100:undefined,axisLabel:{formatter:(v:number)=>v.toLocaleString('zh-CN')}},dataZoom:rows.length>60?[{type:'inside'},{type:'slider',height:16,bottom:0}]:[],series:keys.map(k=>({name:labels[k],type:'line',smooth:.3,smoothMonotone:'x',showSymbol:rows.length<=2,connectNulls:false,data:rows.map((r:any)=>r.requests?r[k]:['average_ttft_ms','average_tokens_per_second','success_rate'].includes(k)?null:0),symbolSize:5,lineStyle:{width:2.2}})),graphic:hasData.value?[]:[{type:'text',left:'center',top:'middle',style:{text:'所选区间暂无推理请求',fill:'#73849b'}}]});chart.setOption(chartTheme());chart.on('click',(event:any)=>{if(event.componentType==='series')timelineLogs(rows[event.dataIndex])})}
function resizeChart(){chart?.resize()}
const observer=new ResizeObserver(resizeChart)
watch([result,chartMetric,dark],renderChart)
watch(chartHost,host=>{observer.disconnect();if(host)observer.observe(host)})
onBeforeUnmount(()=>{generation++;controller?.abort();optionController?.abort();observer.disconnect();chart?.dispose()})
watch(()=>route.fullPath,load,{immediate:true})
watch(admin,()=>{result.value=null;options.value={};applied.value={};void loadOptions()},{immediate:true})
function exportRows(kind:'dimension'|'time'){
 const rows=kind==='dimension'?breakdownRows.value:result.value.series,fields=kind==='dimension'?['label','value',...tableMetrics,'request_share','token_share','usage_unavailable']:['bucket',...tableMetrics,'usage_unavailable']
 const cell=(v:any)=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"'
 const title=(k:string)=>k==='label'?labels[result.value.dimension]:k==='value'?'名称 / ID':k==='bucket'?'时间 · '+branding.timezone:labels[k]+(unit(k)?'（'+unit(k)+'）':'')
 const csv='\uFEFF'+[fields.map(k=>cell(title(k))).join(','),...rows.map((r:any)=>fields.map(k=>cell(k==='bucket'?formatDate(r[k]):r[k])).join(','))].join('\r\n')
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),link=document.createElement('a');link.href=url;link.download='用量统计-'+(kind==='dimension'?labels[result.value.dimension]:'时间趋势')+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
}
</script>
<template><div><PageHeader :title="admin?'用量统计':'我的用量'"><el-button :loading="loading" @click="load">刷新数据</el-button></PageHeader>
<el-alert v-if="error" :title="error" :description="result?'当前保留上次成功查询结果，请重试。':''" type="error" :closable="false"/>
<div class="panel usage-filter-panel"><div class="quick-ranges"><span>快捷时间</span><el-button v-for="p in [{value:'today',label:'今天'},{value:'24',label:'最近 24 小时'},{value:'168',label:'最近 7 天'},{value:'720',label:'最近 30 天'}]" :key="p.value" text @click="preset(p.value)">{{p.label}}</el-button></div>
<div class="usage-filter-grid"><div v-for="k in visibleFilters" :key="k" class="filter-field"><label>{{labels[k]}}</label><el-select v-model="filters[k]" filterable clearable :allow-create="k!=='operation'" :loading="optionsLoading" :aria-label="labels[k]" :placeholder="'全部'+labels[k]"><el-option v-for="o in choices(k)" :key="o.value" :label="o.label" :value="o.value"/></el-select></div><div class="filter-field"><label>模型匹配</label><el-select v-model="modelScope" aria-label="模型匹配"><el-option label="请求或实际模型" value="either"/><el-option label="仅请求模型（含虚拟模型）" value="request"/><el-option label="仅实际模型" value="actual"/></el-select></div></div>
<div class="filter-footer"><el-date-picker v-model="range" type="datetimerange" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间" aria-label="统计时间范围"/><el-select v-model="grain" aria-label="时间粒度" class="grain-select"><el-option label="按天统计" value="day"/><el-option label="按小时统计" value="hour"/></el-select><el-button type="primary" :loading="loading" @click="search">查询</el-button><el-button @click="reset">重置</el-button><el-button v-if="admin" @click="advanced=!advanced">{{advanced?'收起筛选':'更多筛选'}}</el-button></div>
<div v-if="optionError" class="option-error">{{optionError}} <el-button link type="primary" @click="loadOptions">重试</el-button></div>
<div v-if="chips.length" class="active-filters"><span>已应用</span><el-tag v-for="chip in chips" :key="chip.key" closable @close="removeChip(chip.key)">{{chip.label}}</el-tag></div></div>
<el-skeleton v-if="loading&&!result" :rows="10" animated/>
<template v-if="result"><div class="result-context"><span>{{formatDate(result.start)}} — {{formatDate(result.end)}}</span><span class="muted">{{result.grain==='hour'?'按小时':'按天'}} · {{branding.timezone}}</span><router-link v-if="logAvailable" :to="{path:'/admin/call-logs',query:logQuery()}" class="usage-link">查看对应调用日志 →</router-link><span v-else-if="admin" class="muted">调用日志最多支持 31 天，请缩小时间范围后查看</span></div>
<section class="usage-cards" v-loading="loading"><div v-for="k in cards" :key="k" class="usage-card"><span>{{labels[k]}}</span><strong>{{formatMetric(k,result.summary[k])}}<small>{{unit(k)}}</small></strong><div class="card-detail" v-if="k==='requests'">成功 {{formatMetric('success',result.summary.success)}} · 失败 / 取消 {{formatMetric('failure',result.summary.failure)}}</div><div class="card-detail" v-else-if="k==='total_tokens'">已上报用量，不估算缺失字段</div><div class="card-detail" v-else-if="k==='token_coverage'">{{formatMetric('usage_unavailable',result.summary.usage_unavailable)}} 个请求字段不完整</div><div class="card-detail" v-else-if="k==='cached_tokens'">缓存为输入用量子集，不重复累加</div></div></section>
<details class="usage-notes"><summary>统计口径与数据完整性</summary><p>仅统计已完成的推理请求；筛选范围左闭右开，分桶按北京时间，显示时间使用 {{branding.timezone}}。智能路由向量子请求单独计数。请求模型为客户端填写名称，实际模型为最终使用的逻辑模型；未进入上游的请求可能没有实际模型或账号。</p><p>Token 按上游已上报字段求和，未上报显示“—”，零用量显示“0”。总 Token 使用上游总值；缓存 Token 不重复累加。完整率统计输入、输出、总 Token 都已上报的请求比例，Embedding 等接口未提供输出字段时也标为不完整。</p><p>首字延迟仅包含观测到有效内容块的流式请求；生成速率为输出 Token ÷ 生成时长，非流式采用上游整包响应时长。均值按有效样本计算，缺失不填零。</p></details>
<div class="performance-strip"><span>平均首字延迟 <strong>{{formatMetric('average_ttft_ms',result.summary.average_ttft_ms)}} ms</strong><small>{{result.summary.ttft_samples}} 个有效样本</small></span><span>平均生成速率 <strong>{{formatMetric('average_tokens_per_second',result.summary.average_tokens_per_second)}} Token/s</strong><small>{{result.summary.tps_samples}} 个有效样本</small></span></div>
<div class="panel usage-section" v-loading="loading"><div class="section-toolbar"><h2>时间趋势</h2><el-select v-model="chartMetric" aria-label="趋势指标"><el-option v-for="o in chartMetrics" :key="o.value" :label="o.label" :value="o.value"/></el-select><span v-if="logAvailable" class="muted">点击数据点查看该时段日志</span><el-button class="export-button" :disabled="!hasData" @click="exportRows('time')">导出时间明细</el-button></div><div ref="chartHost" class="usage-chart"></div>
<el-table :data="visibleTimeline" stripe><el-table-column :label="'时间 · '+branding.timezone" min-width="200" fixed><template #default="s"><el-button v-if="logAvailable&&s.row.requests" link type="primary" @click="timelineLogs(s.row)">{{formatDate(s.row.bucket)}}</el-button><span v-else>{{formatDate(s.row.bucket)}}</span></template></el-table-column><el-table-column v-for="k in tableMetrics" :key="k" :label="labels[k]+(unit(k)?' · '+unit(k):'')" min-width="135" align="right"><template #default="s">{{formatMetric(k,s.row[k])}}</template></el-table-column></el-table><el-pagination v-model:current-page="timePage" :total="result.series.length" :page-size="12" layout="total, prev, pager, next" class="usage-pagination"/></div>
<div class="panel usage-section" v-loading="loading"><div class="section-toolbar"><h2>维度分析</h2><el-select v-model="dimension" aria-label="统计维度" @change="search"><el-option v-for="k in dimensionKeys" :key="k" :label="'按'+labels[k]" :value="k"/></el-select><span class="muted">占比基于当前筛选结果</span><el-button class="export-button" :disabled="!hasData" @click="exportRows('dimension')">导出维度明细</el-button></div><p v-if="result.dimension_count>result.breakdown_limit" class="muted">共 {{result.dimension_count}} 个分项，按已上报 Token 展示前 {{result.breakdown_limit}} 项；汇总与占比使用全部分项。</p>
<el-table :data="visibleBreakdown" stripe @sort-change="sortRows" empty-text="当前筛选范围暂无数据"><el-table-column :label="labels[result.dimension]" min-width="230" fixed><template #default="s"><strong class="dimension-name">{{result.dimension==='operation'?labelFor('operation',s.row.value):s.row.label}}</strong><small v-if="result.dimension?.endsWith('_id')&&s.row.value!=='0'" class="muted">ID {{s.row.value}}</small></template></el-table-column><el-table-column label="请求占比" width="145" align="right"><template #default="s"><span>{{formatMetric('request_share',s.row.request_share)}}%</span><el-progress :percentage="s.row.request_share" :show-text="false" :stroke-width="4"/></template></el-table-column><el-table-column v-for="k in tableMetrics" :key="k" :prop="k" :label="labels[k]+(unit(k)?' · '+unit(k):'')" min-width="135" align="right" sortable="custom"><template #default="s">{{formatMetric(k,s.row[k])}}</template></el-table-column><el-table-column label="Token 占比" width="120" align="right"><template #default="s">{{formatMetric('token_share',s.row.token_share)}}{{s.row.token_share==null?'':'%'}}</template></el-table-column><el-table-column v-if="admin" label="操作" width="90" fixed="right"><template #default="s"><el-button link type="primary" :disabled="!logAvailable||!s.row.value||s.row.value==='0'" @click="drill(s.row)">日志</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="dimensionPage" :total="breakdownRows.length" :page-size="10" layout="total, prev, pager, next" class="usage-pagination"/></div>
</template></div></template>
<style scoped>
.usage-filter-panel{padding:20px 24px}.quick-ranges{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:18px}.quick-ranges>span,.active-filters>span{font-size:13px;color:var(--muted);margin-right:10px}.quick-ranges :deep(.el-button+.el-button){margin-left:0}.usage-filter-grid{display:grid;grid-template-columns:repeat(4,minmax(160px,1fr));gap:16px}.filter-field label{display:block;color:var(--muted);font-size:13px;margin-bottom:8px}.filter-field .el-select{width:100%}.filter-footer{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:20px}.filter-footer :deep(.el-date-editor){flex:1;min-width:320px}.filter-footer :deep(.el-button+.el-button){margin-left:0}.grain-select{width:130px}.option-error{margin-top:14px;color:var(--el-color-warning);font-size:13px}.active-filters{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:18px}.result-context{display:flex;gap:14px;align-items:center;flex-wrap:wrap;font-size:13px;margin:24px 0 16px}.usage-link{color:var(--el-color-primary);margin-left:auto}.usage-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.usage-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:20px 22px}.usage-card>span{display:block;color:var(--muted);font-size:13px}.usage-card strong{display:block;font-size:30px;line-height:1.4;margin-top:8px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.usage-card small{font-size:14px;margin-left:6px;color:var(--muted);font-weight:400}.card-detail{font-size:12px;color:var(--muted);margin-top:8px;min-height:18px}.usage-notes{font-size:13px;color:var(--muted);margin:20px 0;line-height:1.8}.usage-notes summary{cursor:pointer}.performance-strip{display:flex;flex-wrap:wrap;gap:24px;margin:20px 0}.performance-strip>span{font-size:13px;color:var(--muted)}.performance-strip strong{margin:0 10px;color:var(--el-text-color-primary);font-size:16px}.performance-strip small{font-size:12px}.usage-section{margin-top:20px}.se